<script>
export default {
  name: 'App',

  data () {
    return {
      toastTimer: null
    }
  },

  computed: {
    snackbar () {
      return this.$store.state.snackbar
    }
  },

  watch: {
    'snackbar.show' (show) {
      window.clearTimeout(this.toastTimer)
      if (show) {
        this.toastTimer = window.setTimeout(() => this.closeSnackbar(), 4000)
      }
    }
  },

  beforeUnmount () {
    window.clearTimeout(this.toastTimer)
  },

  methods: {
    closeSnackbar () {
      this.$store.commit('closeSnackbar')
    }
  }
}
</script>